/** Lazy refill: no background thread, no timer. Tokens are computed from
 *  elapsed time at the moment they are needed — which is why this is O(1)
 *  space per client and survives a process that was paused for an hour. */
final class TokenBucket {
    private final double capacity;      // burst size
    private final double refillPerNano; // steady-state rate
    private double tokens;
    private long lastRefillNanos;

    synchronized boolean allow() {
        long now = System.nanoTime();   // monotonic: never walks backwards
        tokens = Math.min(capacity, tokens + (now - lastRefillNanos) * refillPerNano);
        lastRefillNanos = now;

        if (tokens < 1.0) return false;
        tokens -= 1.0;
        return true;
    }
}

/** O(1) memory, and it does not have the fixed-window boundary bug. The
 *  estimate assumes traffic was uniform in the previous window — which is
 *  the approximation you are agreeing to, and should say so. */
boolean allow(long nowMillis) {
    long window = nowMillis / windowMillis;
    if (window != currentWindow) {
        previousCount = (window == currentWindow + 1) ? currentCount : 0;
        currentCount = 0;
        currentWindow = window;
    }

    double elapsed = (nowMillis % windowMillis) / (double) windowMillis;
    double estimate = previousCount * (1 - elapsed) + currentCount;

    if (estimate >= limit) return false;
    currentCount++;
    return true;
}

class Logger {
    private final Map<String, Integer> lastPrinted = new HashMap<>();

    public boolean shouldPrintMessage(int timestamp, String message) {
        Integer last = lastPrinted.get(message);
        if (last != null && timestamp < last + 10) return false;
        lastPrinted.put(message, timestamp);
        return true;
    }
}
